package io.lumine.mythic.lib.skill.parameter;
import io.lumine.mythic.lib.skill.parameter.value.*; import java.text.DecimalFormat;
public class SkillParameter { public static final DecimalFormat DEFAULT_DECIMAL_FORMAT=new DecimalFormat("0.##"); private final String translate; private final double itemDefault; private final ScalingFormula formula; private final DecimalFormat format; public SkillParameter(String translate,double itemDefault,ScalingFormula formula,DecimalFormat format){this.translate=translate;this.itemDefault=itemDefault;this.formula=formula==null?ScalingFormula.ZERO:formula;this.format=format==null?DEFAULT_DECIMAL_FORMAT:format;} public String getTranslate(){return translate;} public double getItemDefaultValue(){return itemDefault;} public DecimalFormat getDecimalFormat(){return format;} public ScalingFormula getScalingFormula(){return formula;} public String format(double v){return format.format(v);} public static SkillParameter empty(String key){return new SkillParameter(key,0,ScalingFormula.ZERO,DEFAULT_DECIMAL_FORMAT);} public static SkillParameter fromConfig(Object o,String key){if(o instanceof Number n)return new SkillParameter(key,n.doubleValue(),new NonScalingFormula(n.doubleValue()),DEFAULT_DECIMAL_FORMAT);return empty(key);} }
